// grammar of RFC 6733 §7.2, so only the AVPs it had are written.
func (m *ReAuthAnswer) AppendAVPs(b []byte) []byte {
	var s int
	if m.Header.Flags&diam.FlagError == 0 || !m.decoded || m.seen&(uint64(1)<<0) != 0 {
		b, s = diam.BeginAVP(b, 263, diam.AVPFlagMandatory, 0)
		b = append(b, m.SessionId...)
		b = diam.EndAVP(b, s)
	}
	if m.Header.Flags&diam.FlagError == 0 || !m.decoded || m.seen&(uint64(1)<<1) != 0 {
		b, s = diam.BeginAVP(b, 268, diam.AVPFlagMandatory, 0)
		b = diam.AppendUnsigned32(b, m.ResultCode)
		b = diam.EndAVP(b, s)
	}
	if m.Header.Flags&diam.FlagError == 0 || !m.decoded || m.seen&(uint64(1)<<2) != 0 {
		b, s = diam.BeginAVP(b, 264, diam.AVPFlagMandatory, 0)
		b = append(b, m.OriginHost...)
		b = diam.EndAVP(b, s)
	}
	if m.Header.Flags&diam.FlagError == 0 || !m.decoded || m.seen&(uint64(1)<<3) != 0 {
		b, s = diam.BeginAVP(b, 296, diam.AVPFlagMandatory, 0)
		b = append(b, m.OriginRealm...)
		b = diam.EndAVP(b, s)
	}
	if m.UserName.Set {
		b, s = diam.BeginAVP(b, 1, diam.AVPFlagMandatory, 0)
		b = append(b, m.UserName.V...)
		b = diam.EndAVP(b, s)
	}
	if m.OriginStateId.Set {
		b, s = diam.BeginAVP(b, 278, diam.AVPFlagMandatory, 0)
		b = diam.AppendUnsigned32(b, m.OriginStateId.V)
		b = diam.EndAVP(b, s)
	}
	if m.ErrorMessage.Set {
		b, s = diam.BeginAVP(b, 281, 0, 0)
		b = append(b, m.ErrorMessage.V...)
		b = diam.EndAVP(b, s)
	}
	if m.ErrorReportingHost.Set {
		b, s = diam.BeginAVP(b, 294, 0, 0)
		b = append(b, m.ErrorReportingHost.V...)
		b = diam.EndAVP(b, s)
	}
	if m.FailedAvp != nil {
		b, s = diam.BeginAVP(b, 279, diam.AVPFlagMandatory, 0)
		b = m.FailedAvp.AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	for i := range m.RedirectHost {
		b, s = diam.BeginAVP(b, 292, diam.AVPFlagMandatory, 0)
		b = append(b, m.RedirectHost[i]...)
		b = diam.EndAVP(b, s)
	}
	if m.RedirectHostUsage.Set {
		b, s = diam.BeginAVP(b, 261, diam.AVPFlagMandatory, 0)
		b = diam.AppendInteger32(b, int32(m.RedirectHostUsage.V))
		b = diam.EndAVP(b, s)
	}
	if m.RedirectMaxCacheTime.Set {
		b, s = diam.BeginAVP(b, 262, diam.AVPFlagMandatory, 0)
		b = diam.AppendUnsigned32(b, m.RedirectMaxCacheTime.V)
		b = diam.EndAVP(b, s)
	}
	for i := range m.ProxyInfo {
		b, s = diam.BeginAVP(b, 284, diam.AVPFlagMandatory, 0)
		b = (&m.ProxyInfo[i]).AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	for _, a := range m.Unknown {
		b = diam.AppendRaw(b, a)
	}
	return b
}

// DecodeAVPs replaces the AVPs of m with those of an AVP sequence; the
// Header is kept.
// It fails only when the sequence
// itself cannot be split into AVPs. AVPs that the grammar does not describe
// go to Unknown; a value that cannot be decoded and an occurrence beyond a
// maximum are skipped and reported by Validate.
func (m *ReAuthAnswer) DecodeAVPs(data []byte) error {
	*m = ReAuthAnswer{Header: m.Header}
	m.decoded = true
	idx := -1
	for len(data) > 0 {
		a, rest, err := diam.NextAVP(data)
		if err != nil {
			return err
		}
		data = rest
		idx++
		// A V-bit with Vendor-Id 0 is not the IETF AVP of that code.
		if a.Vendor == 0 && a.Flags&diam.AVPFlagVendor != 0 {
			m.Unknown = append(m.Unknown, diam.Clone(a))
			continue
		}
		switch uint64(a.Vendor)<<32 | uint64(a.Code) {
		case 263: // SESSION_ID code 263
			if m.seen&(uint64(1)<<0) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "SESSION_ID")
				}
				continue
			}
			if idx != 0 && m.misplaced == nil {
				m.misplaced = diam.Misplaced(diam.Clone(a), "SESSION_ID")
			}
			m.seen |= uint64(1) << 0
			m.SessionId = string(a.Data)
		case 268: // RESULT_CODE code 268
			if m.seen&(uint64(1)<<1) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "RESULT_CODE")
				}
				continue
			}
			v, err := diam.Unsigned32(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.seen |= uint64(1) << 1
			m.ResultCode = v
		case 264: // ORIGIN_HOST code 264
			if m.seen&(uint64(1)<<2) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "ORIGIN_HOST")
				}
				continue
			}
			m.seen |= uint64(1) << 2
			m.OriginHost = string(a.Data)
		case 296: // ORIGIN_REALM code 296
			if m.seen&(uint64(1)<<3) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "ORIGIN_REALM")
				}
				continue
			}
			m.seen |= uint64(1) << 3
			m.OriginRealm = string(a.Data)
		case 1: // USER_NAME code 1
			if m.UserName.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "USER_NAME")
				}
				continue
			}
			m.UserName = diam.Some(string(a.Data))
		case 278: // ORIGIN_STATE_ID code 278
			if m.OriginStateId.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "ORIGIN_STATE_ID")
				}
				continue
			}
			v, err := diam.Unsigned32(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.OriginStateId = diam.Some(v)
		case 281: // ERROR_MESSAGE code 281
			if m.ErrorMessage.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "ERROR_MESSAGE")
				}
				continue
			}
			m.ErrorMessage = diam.Some(string(a.Data))
		case 294: // ERROR_REPORTING_HOST code 294
			if m.ErrorReportingHost.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "ERROR_REPORTING_HOST")
				}
				continue
			}
			m.ErrorReportingHost = diam.Some(string(a.Data))
		case 279: // FAILED_AVP code 279
			if m.FailedAvp != nil {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "FAILED_AVP")
				}
				continue
			}
			var v FailedAvp
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP FAILED_AVP"}
				}
				continue
			}
			m.FailedAvp = &v
		case 292: // REDIRECT_HOST code 292
			m.RedirectHost = append(m.RedirectHost, string(a.Data))
		case 261: // REDIRECT_HOST_USAGE code 261
			if m.RedirectHostUsage.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "REDIRECT_HOST_USAGE")
				}
				continue
			}
			v, err := diam.Integer32(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.RedirectHostUsage = diam.Some(RedirectHostUsage(v))
		case 262: // REDIRECT_MAX_CACHE_TIME code 262
			if m.RedirectMaxCacheTime.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "REDIRECT_MAX_CACHE_TIME")
				}
				continue
			}
			v, err := diam.Unsigned32(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.RedirectMaxCacheTime = diam.Some(v)
		case 284: // PROXY_INFO code 284
			var v ProxyInfo
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP PROXY_INFO"}
				}
				continue
			}
			m.ProxyInfo = append(m.ProxyInfo, v)
		default:
			m.Unknown = append(m.Unknown, diam.Clone(a))
		}
	}
	return nil
}

// Validate checks m against its grammar and returns the first violation
// as a *diam.AVPError. Required presence is checked on decoded messages
// only: a zero value is a valid encoding, so a hand-built message has
// nothing to check.
func (m *ReAuthAnswer) Validate() error {
	if m.decodeErr != nil {
		return m.decodeErr
	}
	if m.excess != nil {
		return m.excess
	}
	if m.Header.Flags&diam.FlagError != 0 {
		return m.validateError()
	}
	if m.decoded && m.seen&(uint64(1)<<0) == 0 {
		return diam.Missing(263, 0, "SESSION_ID")
	}
	if m.decoded && m.seen&(uint64(1)<<1) == 0 {
		return diam.Missing(268, 0, "RESULT_CODE")
	}
	if m.decoded && m.seen&(uint64(1)<<2) == 0 {
		return diam.Missing(264, 0, "ORIGIN_HOST")
	}
	if m.decoded && m.seen&(uint64(1)<<3) == 0 {
		return diam.Missing(296, 0, "ORIGIN_REALM")
	}
	if m.misplaced != nil {
		return m.misplaced
	}
	if m.FailedAvp != nil {
		if err := m.FailedAvp.Validate(); err != nil {
			return diam.InGroup(err, 279)
		}
	}
	for i := range m.ProxyInfo {
		if err := m.ProxyInfo[i].Validate(); err != nil {
			return diam.InGroup(err, 284)
		}
	}
	return diam.CheckUnknown(m.Unknown)
}

// validateError checks an answer with the E bit against the answer-message
// grammar of RFC 6733 §7.2, which it follows instead of its command's.
func (m *ReAuthAnswer) validateError() error {
	if m.decoded && !(m.seen&(uint64(1)<<2) != 0) {
		return diam.Missing(264, 0, "ORIGIN_HOST")
	}
	if m.decoded && !(m.seen&(uint64(1)<<3) != 0) {
		return diam.Missing(296, 0, "ORIGIN_REALM")
	}
	if m.decoded && !(m.seen&(uint64(1)<<1) != 0) {
		return diam.Missing(268, 0, "RESULT_CODE")
	}
	if m.misplaced != nil {
		return m.misplaced
	}
	if m.FailedAvp != nil {
		if err := m.FailedAvp.Validate(); err != nil {
			return diam.InGroup(err, 279)
		}
	}
	for i := range m.ProxyInfo {
		if err := m.ProxyInfo[i].Validate(); err != nil {
			return diam.InGroup(err, 284)
		}
	}
	return diam.CheckUnknownError(m.Unknown)
}

// DiamHeader implements diam.Message.
func (m *ReAuthAnswer) DiamHeader() *diam.Header { return &m.Header }

// AppendMarshal appends the encoded message to b. The command code, the
// application id and the R and P bits come from the grammar; the E and T
// bits and the identifiers come from m.Header, which is not modified.
func (m *ReAuthAnswer) AppendMarshal(b []byte) ([]byte, error) {
	h := m.Header
	h.CommandCode, h.AppID = 258, 0
	h.Flags = h.Flags&^(diam.FlagRequest|diam.FlagProxiable) | diam.FlagProxiable
	start := len(b)
	b = diam.AppendHeader(b, &h)
	b = m.AppendAVPs(b)
	return diam.FinishMessage(b, start)
}

// Marshal encodes the message.
func (m *ReAuthAnswer) Marshal() ([]byte, error) { return m.AppendMarshal(nil) }

// Unmarshal decodes a whole message into m, replacing its contents. It
// fails only when the message cannot be framed; grammar violations are
// reported by Validate.
func (m *ReAuthAnswer) Unmarshal(b []byte) error {
	h, avps, err := diam.ParseHeader(b)
	if err != nil {
		return err
	}
	m.Header = h
	return m.DecodeAVPs(avps)
}

// <STR>  ::= < Diameter Header: 275, REQ, PXY >
//
//	  < Session-Id >
//	  { Origin-Host }
//	  { Origin-Realm }
//	  { Destination-Realm }
//	  { Auth-Application-Id }
//	  { Termination-Cause }
//	  [ User-Name ]
//	  [ Destination-Host ]
//	* [ Class ]
//	  [ Origin-State-Id ]
//	* [ Proxy-Info ]
//	* [ Route-Record ]
//	* [ AVP ]
type SessionTerminationRequest struct {
	Header diam.Header

	SessionId         string           // < > SESSION_ID code 263
	OriginHost        string           // { } ORIGIN_HOST code 264
	OriginRealm       string           // { } ORIGIN_REALM code 296
	DestinationRealm  string           // { } DESTINATION_REALM code 283
	AuthApplicationId uint32           // { } AUTH_APPLICATION_ID code 258
	TerminationCause  TerminationCause // { } TERMINATION_CAUSE code 295
	UserName          diam.Opt[string] // [ ] USER_NAME code 1
	DestinationHost   diam.Opt[string] // [ ] DESTINATION_HOST code 293
	Class             [][]byte         // *[ ] CLASS code 25
	OriginStateId     diam.Opt[uint32] // [ ] ORIGIN_STATE_ID code 278
	ProxyInfo         []ProxyInfo      // *[ ] PROXY_INFO code 284
	RouteRecord       []string         // *[ ] ROUTE_RECORD code 282

	// Unknown holds AVPs not described above. They are re-encoded verbatim.
	Unknown []diam.RawAVP

	seen      uint64 // required AVPs found by DecodeAVPs
	decodeErr error  // first AVP whose value could not be decoded
	excess    error  // first occurrence beyond the grammar maximum
	misplaced error  // first fixed-position AVP found elsewhere
	decoded   bool   // set by DecodeAVPs; required presence is checked only then
}

// AppendAVPs appends the AVPs of m: fixed-position AVPs, the others in
// grammar order, then Unknown. Required AVPs are always written.
func (m *SessionTerminationRequest) AppendAVPs(b []byte) []byte {
	var s int
	b, s = diam.BeginAVP(b, 263, diam.AVPFlagMandatory, 0)
	b = append(b, m.SessionId...)
	b = diam.EndAVP(b, s)
	b, s = diam.BeginAVP(b, 264, diam.AVPFlagMandatory, 0)
	b = append(b, m.OriginHost...)
	b = diam.EndAVP(b, s)
	b, s = diam.BeginAVP(b, 296, diam.AVPFlagMandatory, 0)
	b = append(b, m.OriginRealm...)
	b = diam.EndAVP(b, s)
	b, s = diam.BeginAVP(b, 283, diam.AVPFlagMandatory, 0)
	b = append(b, m.DestinationRealm...)
	b = diam.EndAVP(b, s)
	b, s = diam.BeginAVP(b, 258, diam.AVPFlagMandatory, 0)
	b = diam.AppendUnsigned32(b, m.AuthApplicationId)
	b = diam.EndAVP(b, s)
	b, s = diam.BeginAVP(b, 295, diam.AVPFlagMandatory, 0)
	b = diam.AppendInteger32(b, int32(m.TerminationCause))
	b = diam.EndAVP(b, s)
	if m.UserName.Set {
		b, s = diam.BeginAVP(b, 1, diam.AVPFlagMandatory, 0)
		b = append(b, m.UserName.V...)
		b = diam.EndAVP(b, s)
	}
	if m.DestinationHost.Set {
		b, s = diam.BeginAVP(b, 293, diam.AVPFlagMandatory, 0)
		b = append(b, m.DestinationHost.V...)
		b = diam.EndAVP(b, s)
	}
	for i := range m.Class {
		b, s = diam.BeginAVP(b, 25, diam.AVPFlagMandatory, 0)
		b = append(b, m.Class[i]...)
		b = diam.EndAVP(b, s)
	}
	if m.OriginStateId.Set {
		b, s = diam.BeginAVP(b, 278, diam.AVPFlagMandatory, 0)
		b = diam.AppendUnsigned32(b, m.OriginStateId.V)
		b = diam.EndAVP(b, s)
	}
	for i := range m.ProxyInfo {
		b, s = diam.BeginAVP(b, 284, diam.AVPFlagMandatory, 0)
		b = (&m.ProxyInfo[i]).AppendAVPs(b)
		b = diam.EndAVP(b, s)
	}
	for i := range m.RouteRecord {
		b, s = diam.BeginAVP(b, 282, diam.AVPFlagMandatory, 0)
		b = append(b, m.RouteRecord[i]...)
		b = diam.EndAVP(b, s)
	}
	for _, a := range m.Unknown {
		b = diam.AppendRaw(b, a)
	}
	return b
}

// DecodeAVPs replaces the AVPs of m with those of an AVP sequence; the
// Header is kept.
// It fails only when the sequence
// itself cannot be split into AVPs. AVPs that the grammar does not describe
// go to Unknown; a value that cannot be decoded and an occurrence beyond a
// maximum are skipped and reported by Validate.
func (m *SessionTerminationRequest) DecodeAVPs(data []byte) error {
	*m = SessionTerminationRequest{Header: m.Header}
	m.decoded = true
	idx := -1
	for len(data) > 0 {
		a, rest, err := diam.NextAVP(data)
		if err != nil {
			return err
		}
		data = rest
		idx++
		// A V-bit with Vendor-Id 0 is not the IETF AVP of that code.
		if a.Vendor == 0 && a.Flags&diam.AVPFlagVendor != 0 {
			m.Unknown = append(m.Unknown, diam.Clone(a))
			continue
		}
		switch uint64(a.Vendor)<<32 | uint64(a.Code) {
		case 263: // SESSION_ID code 263
			if m.seen&(uint64(1)<<0) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "SESSION_ID")
				}
				continue
			}
			if idx != 0 && m.misplaced == nil {
				m.misplaced = diam.Misplaced(diam.Clone(a), "SESSION_ID")
			}
			m.seen |= uint64(1) << 0
			m.SessionId = string(a.Data)
		case 264: // ORIGIN_HOST code 264
			if m.seen&(uint64(1)<<1) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "ORIGIN_HOST")
				}
				continue
			}
			m.seen |= uint64(1) << 1
			m.OriginHost = string(a.Data)
		case 296: // ORIGIN_REALM code 296
			if m.seen&(uint64(1)<<2) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "ORIGIN_REALM")
				}
				continue
			}
			m.seen |= uint64(1) << 2
			m.OriginRealm = string(a.Data)
		case 283: // DESTINATION_REALM code 283
			if m.seen&(uint64(1)<<3) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "DESTINATION_REALM")
				}
				continue
			}
			m.seen |= uint64(1) << 3
			m.DestinationRealm = string(a.Data)
		case 258: // AUTH_APPLICATION_ID code 258
			if m.seen&(uint64(1)<<4) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "AUTH_APPLICATION_ID")
				}
				continue
			}
			v, err := diam.Unsigned32(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.seen |= uint64(1) << 4
			m.AuthApplicationId = v
		case 295: // TERMINATION_CAUSE code 295
			if m.seen&(uint64(1)<<5) != 0 {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "TERMINATION_CAUSE")
				}
				continue
			}
			v, err := diam.Integer32(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.seen |= uint64(1) << 5
			m.TerminationCause = TerminationCause(v)
		case 1: // USER_NAME code 1
			if m.UserName.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "USER_NAME")
				}
				continue
			}
			m.UserName = diam.Some(string(a.Data))
		case 293: // DESTINATION_HOST code 293
			if m.DestinationHost.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "DESTINATION_HOST")
				}
				continue
			}
			m.DestinationHost = diam.Some(string(a.Data))
		case 25: // CLASS code 25
			v, _ := diam.Bytes(a)
			m.Class = append(m.Class, v)
		case 278: // ORIGIN_STATE_ID code 278
			if m.OriginStateId.Set {
				if m.excess == nil {
					m.excess = diam.TooMany(diam.Clone(a), "ORIGIN_STATE_ID")
				}
				continue
			}
			v, err := diam.Unsigned32(a)
			if err != nil {
				if m.decodeErr == nil {
					m.decodeErr = err
				}
				continue
			}
			m.OriginStateId = diam.Some(v)
		case 284: // PROXY_INFO code 284
			var v ProxyInfo
			if err := v.DecodeAVPs(a.Data); err != nil {
				if m.decodeErr == nil {
					m.decodeErr = &diam.AVPError{ResultCode: diam.ResultInvalidAVPLength, AVP: diam.Clone(a), Msg: "malformed grouped AVP PROXY_INFO"}
				}
				continue
			}
			m.ProxyInfo = append(m.ProxyInfo, v)
		case 282: // ROUTE_RECORD code 282
			m.RouteRecord = append(m.RouteRecord, string(a.Data))
		default:
			m.Unknown = append(m.Unknown, diam.Clone(a))
		}
	}
	return nil
}

// Validate checks m against its grammar and returns the first violation
// as a *diam.AVPError. Required presence is checked on decoded messages
// only: a zero value is a valid encoding, so a hand-built message has
// nothing to check.
func (m *SessionTerminationRequest) Validate() error {
	if m.decodeErr != nil {
		return m.decodeErr
	}
	if m.excess != nil {
		return m.excess
	}
	if m.decoded && m.seen&(uint64(1)<<0) == 0 {
		return diam.Missing(263, 0, "SESSION_ID")
	}
	if m.decoded && m.seen&(uint64(1)<<1) == 0 {
		return diam.Missing(264, 0, "ORIGIN_HOST")
	}
	if m.decoded && m.seen&(uint64(1)<<2) == 0 {
		return diam.Missing(296, 0, "ORIGIN_REALM")
	}
	if m.decoded && m.seen&(uint64(1)<<3) == 0 {
		return diam.Missing(283, 0, "DESTINATION_REALM")
	}
	if m.decoded && m.seen&(uint64(1)<<4) == 0 {
		return diam.Missing(258, 0, "AUTH_APPLICATION_ID")
	}
	if m.decoded && m.seen&(uint64(1)<<5) == 0 {
		return diam.Missing(295, 0, "TERMINATION_CAUSE")
	}
	if m.misplaced != nil {
		return m.misplaced
	}
	for i := range m.ProxyInfo {
		if err := m.ProxyInfo[i].Validate(); err != nil {
			return diam.InGroup(err, 284)
		}
	}
	return diam.CheckUnknown(m.Unknown)
}

